                val = nums2[order[m]]
                if len(heap) < k:
                    heapq.heappush(heap, val)
                    cur_sum += val
                elif val > heap[0]:
                    cur_sum += val - heap[0]
                    heapq.heapreplace(heap, val)

            i = j

        return answer
